    ('東京国際空港', null, '東京都', 35.5536173, 139.7713306, 'A', 'その他', '東京国際空港（とうきょうこくさいくうこう、英語: Tokyo International Airport、IATA: HND, ICAO: RJTT）は、東京都大田区羽田空港に所在する日本の国際空港の一つ。'),
    ('東京国立近代美術館', 'とうきょうこくりつきんだいびじゅつかん', '東京都', 35.6905083, 139.7546528, 'C', '美術館博物館', '近現代の日本美術を中心に収蔵する国立美術館。'),
    ('東京国立博物館', 'とうきょうこくりつはくぶつかん', '東京都', 35.7190556, 139.7766667, 'A', '美術館博物館', '日本最古・最大級の博物館、国宝・重要文化財を多数収蔵。'),
    ('東京消防庁消防防災資料センター消防博物館', null, '東京都', 35.6881372, 139.7199391, 'C', '美術館博物館', null),
    ('東京体育館', null, '東京都', 35.6797748, 139.7124964, 'A', 'その他', '東京体育館（とうきょうたいいくかん、英: Tokyo Gymnasium）は、東京都渋谷区千駄ヶ谷一丁目にある東京都所有の体育館。'),
    ('東京大学大学院理学系研究科附属植物園', null, '東京都', 35.720355, 139.7437765, 'B', 'その他', '東京大学大学院理学系研究科附属植物園（とうきょうだいがくだいがくいんりがくけいけんきゅうかふぞくしょくぶつえん、英: Botanical Gardens, Graduate School of Science, the University of Tokyo）は、東京都文京区白山三丁目にある植物園。'),
    ('東京大空襲・戦災資料センター', null, '東京都', 35.681744, 139.822264, 'C', '美術館博物館', null),
    ('東京大神宮', null, '東京都', 35.7000073, 139.7468581, 'B', '神社仏閣', '東京大神宮（とうきょうだいじんぐう）は、東京都千代田区富士見二丁目にある神社。天照皇大神・豊受大神を主祭神とする。'),
    ('東京都現代美術館', null, '東京都', 35.6794922, 139.8075046, 'B', '美術館博物館', '東京都現代美術館（とうきょうとげんだいびじゅつかん）は、東京都江東区三好四丁目にある、現代美術専門の公立美術館。'),
    ('東京都写真美術館', null, '東京都', 35.641543, 139.7133962, 'E', '美術館博物館', null),
    ('東京都水道歴史館', null, '東京都', 35.7033139, 139.7604984, 'C', '美術館博物館', null),
    ('東京都庭園美術館', null, '東京都', 35.6367979, 139.7191582, 'B', '美術館博物館', '東京都庭園美術館（とうきょうと ていえん びじゅつかん）は、東京都港区白金台にある都立美術館である。'),
    ('東京都薬用植物園', null, '東京都', 35.7313894, 139.433859, 'C', 'その他', '東京都薬用植物園（とうきょうとやくようしょくぶつえん）は、 東京都小平市中島町にある、薬用植物やハーブを栽培する植物園。'),
    ('東京都立滝山自然公園', null, '東京都', 35.6994149, 139.3273939, 'D', 'その他', '東京都立滝山自然公園（とうきょうとりつたきやましぜんこうえん）は、東京都八王子市にある都立自然公園。'),
    ('東京都檜原都民の森', null, '東京都', 35.7404175, 139.0218343, 'C', 'その他', '東京都檜原都民の森（とうきょうとひのはらとみんのもり）は、東京都西多摩郡檜原村にある施設。'),
    ('東京富士美術館', null, '東京都', 35.686378, 139.3294543, 'B', '美術館博物館', null),
    ('東京臨海広域防災公園', null, '東京都', 35.6347197, 139.7958663, 'B', 'その他', '東京臨海広域防災公園（とうきょうりんかいこういきぼうさいこうえん）は、東京都江東区有明にある広域防災拠点および公園である。'),
    ('東京藝術大学大学美術館', null, '東京都', 35.719192, 139.7719324, 'C', '美術館博物館', null),
    ('東小松川香取神社', null, '東京都', 35.7090811, 139.8673857, 'D', '神社仏閣', null),
    ('東村山中央公園', null, '東京都', 35.7467891, 139.4607525, 'D', 'その他', '東村山中央公園（ひがしむらやまちゅうおうこうえん）は、東京都東村山市にある都立公園。'),
    ('東大和公園', null, '東京都', 35.7541278, 139.4306399, 'D', 'その他', '東大和公園（ひがしやまとこうえん）は、東京都東大和市の狭山丘陵に位置する都立公園。'),
    ('東大和南公園', null, '東京都', 35.7345906, 139.4220316, 'C', 'その他', '東大和南公園（ひがしやまとみなみこうえん）とは、東京都東大和市に存在する都立公園。'),
    ('東白鬚公園', null, '東京都', 35.7321173, 139.8132393, 'C', 'その他', '東白鬚公園（ひがししらひげこうえん）は、東京都墨田区堤通二丁目にある東京都立の公園である。'),
    ('東武博物館', null, '東京都', 35.723464, 139.818985, 'B', '美術館博物館', null),
    ('東本願寺', null, '東京都', 35.7117233, 139.7895232, 'B', '神社仏閣', null),
    ('東洋文庫', null, '東京都', 35.7314731, 139.7482979, 'B', 'その他', '公益財団法人東洋文庫（とうようぶんこ）は、東京都文京区に所在する東洋学の専門図書館、研究所である。'),
    ('湯島天満宮', null, '東京都', 35.7076842, 139.7678622, 'B', '神社仏閣', '湯島天満宮（ゆしまてんまんぐう）は、東京都文京区湯島三丁目にある天満宮で、菅原道真を含む二柱の祭神を祀る神社。通称は湯島天神（ゆしまてんじん）、旧称は湯島神社（ゆしまじんじゃ）。'),
    ('道玄坂', null, '東京都', 35.6579413, 139.698329, 'B', 'その他', '道玄坂（どうげんざか）は、東京都渋谷区にある町名。'),
    ('徳大寺', null, '東京都', 35.7086059, 139.7744835, 'C', '神社仏閣', '徳大寺（とくだいじ）は、東京都台東区上野4丁目アメヤ横丁のほど近くにある日蓮宗の寺院。'),
    ('南池袋公園', null, '東京都', 35.7276629, 139.71432, 'C', 'その他', '豊島区立南池袋公園（みなみいけぶくろこうえん）は、東京都豊島区南池袋にある区立の公園である。'),
    ('二子玉川公園', null, '東京都', 35.609256, 139.632679, 'C', 'その他', '世田谷区立二子玉川公園（せたがやくりつ ふたこたまがわこうえん）は、東京都世田谷区玉川（二子玉川）にある都市公園である。'),
    ('日の出山', null, '東京都', 35.7812407, 139.1674711, 'C', '自然', '日の出山（ひのでやま）は、東京都青梅市御岳2丁目と東京都西多摩郡日の出町大字大久野の境界に位置する、標高902メートルの山である。'),
    ('日枝神社', null, '東京都', 35.6746457, 139.739932, 'A', '神社仏閣', '日枝神社（ひえじんじゃ）は、東京都千代田区永田町二丁目にある、山王信仰の神社。山王さま等とも呼ばれ、江戸三大祭の一つ、山王祭が行われる。'),
    ('日比谷公園', null, '東京都', 35.673889, 139.756191, 'B', 'その他', '日比谷公園（ひびやこうえん）は、東京都千代田区に所在する公園、および同公園を町域とする千代田区の町名である。'),
    ('日比谷公会堂', null, '東京都', 35.6714135, 139.7555498, 'B', 'その他', '日比谷公会堂（ひびやこうかいどう）は、東京都千代田区の日比谷公園の中にある公会堂。'),
    ('日比谷神社', null, '東京都', 35.6633987, 139.7582964, 'B', '神社仏閣', null),
    ('日本カメラ博物館', null, '東京都', 35.6860582, 139.7428472, 'C', '美術館博物館', null),
    ('日本サッカーミュージアム', null, '東京都', 35.7042546, 139.7639427, 'C', '美術館博物館', null),
    ('日本科学未来館', null, '東京都', 35.6193556, 139.777595, 'B', 'その他', '日本科学未来館（にっぽんかがくみらいかん、英称：The National Museum of Emerging Science and Innovation、愛称：Miraikan）は、東京都江東区青海の国際研究交流大学村内にある科学館。'),
    ('日本近代文学館', null, '東京都', 35.6624273, 139.6816433, 'B', 'その他', '公益財団法人日本近代文学館（にほんきんだいぶんがくかん）は、東京都目黒区の駒場公園内に建つ文学館およびそれを運営する公益財団法人。'),
    ('日本銀行金融研究所貨幣博物館', null, '東京都', 35.6854395, 139.7716029, 'C', '美術館博物館', null),
    ('日本民藝館', null, '東京都', 35.660832, 139.6792374, 'B', 'その他', '日本民藝館（にほんみんげいかん）は、東京都目黒区駒場四丁目にある美術館で、「『民藝品の蒐集や保管』『民藝に関する調査研究』『民藝思想の普及』『展覧会』」を軸に活動している。'),
    ('乃木神社', null, '東京都', 35.668586, 139.727995, 'B', '神社仏閣', '乃木神社（のぎじんじゃ）は、東京都港区赤坂にある神社。明治期の軍人・乃木希典（乃木希典命）とその妻・乃木静子（乃木静子命）を祀る。'),
    ('馬事公苑', null, '東京都', 35.6367203, 139.63383, 'B', 'その他', '馬事公苑（ばじこうえん）は、東京都世田谷区上用賀にある公園。'),
    ('馬場大門のケヤキ並木', null, '東京都', 35.6725225, 139.4792613, 'C', 'その他', '馬場大門のケヤキ並木（ばばだいもんのケヤキなみき）は、東京都府中市の大國魂神社参道にあるケヤキ並木。'),
    ('白山神社', null, '東京都', 35.7218967, 139.7505773, 'B', '神社仏閣', '白山神社（はくさんじんじゃ）は、東京都文京区白山にある神社である。旧称白山権現社。'),
    ('白髭神社', null, '東京都', 35.7328433, 139.8403003, 'D', '神社仏閣', null),
    ('畠山記念館', null, '東京都', 35.632242, 139.726938, 'B', '美術館博物館', null),
    ('八王子城', null, '東京都', 35.6528939, 139.2521542, 'A', '城', '八王子城（はちおうじじょう）は、現在の東京都八王子市元八王子町から下恩方町にかけて築かれた日本の山城。'),
    ('八幡社', null, '東京都', 35.6609966, 139.6214486, 'E', '神社仏閣', null),
    ('八芳園', null, '東京都', 35.6384352, 139.7288862, 'B', 'その他', '八芳園（はっぽうえん）は、東京都港区白金台に所在する、1万2000坪の敷地内に庭園のあるレストラン・結婚式場である。'),
    ('鳩ノ巣渓谷', null, '東京都', 35.8131774, 139.1291762, 'C', '自然', '鳩ノ巣渓谷（はとのすけいこく）は、東京都西多摩郡奥多摩町の多摩川上流にある渓谷。'),
    ('板橋区立教育科学館', null, '東京都', 35.7634451, 139.6796239, 'D', '美術館博物館', null),
    ('板橋区立郷土資料館', null, '東京都', 35.7854982, 139.6432063, 'D', '美術館博物館', null),
    ('板橋区立赤塚植物園', null, '東京都', 35.7803542, 139.6440445, 'D', 'その他', '板橋区立赤塚植物園（いたばしくりつあかつかしょくぶつえん、英語:Akatsuka Botanical Garden）は、 東京都板橋区赤塚にある植物園である。'),
    ('碑文谷公園', null, '東京都', 35.625081, 139.682632, 'C', 'その他', '碑文谷公園（ひもんやこうえん）は、東京都目黒区碑文谷にある目黒区立の公園である。'),
    ('肥後細川庭園', null, '東京都', 35.713223, 139.721699, 'C', 'その他', '肥後細川庭園（ひごほそかわていえん）は、東京都文京区目白台にある文京区立の公園。'),
    ('飛鳥山公園', null, '東京都', 35.750757, 139.7384948, 'B', 'その他', '飛鳥山公園（あすかやまこうえん）は、東京都北区にある区立公園。'),
    ('尾久の原公園', null, '東京都', 35.7496192, 139.7758203, 'C', 'その他', '尾久の原公園（おぐのはらこうえん）は、東京都荒川区にある東京都立の公園である。'),
    ('尾根緑道', null, '東京都', 35.6032348, 139.375422, 'C', 'その他', '尾根緑道（おねりょくどう）は、東京都町田市内にある全長およそ8 kmの緑道である。'),
    ('表参道ヒルズ', null, '東京都', 35.6672558, 139.708868, 'B', 'その他', '表参道ヒルズ（おもてさんどうヒルズ、Omotesando Hills）は、東京都渋谷区神宮前（表参道）にあり、商業施設、住宅施設、及び駐車場からなる森ビルの複合商業施設。'),
    ('品川インターシティ', null, '東京都', 35.626704, 139.742174, 'B', 'その他', '品川インターシティ（しながわインターシティ）は、東京都港区港南・品川区北品川にまたがる再開発都市。'),
    ('品川寺', null, '東京都', 35.6095257, 139.7442274, 'B', '神社仏閣', '品川寺（ほんせんじ）は、東京都品川区南品川三丁目にある真言宗醍醐派の寺院である。'),
    ('品川神社', null, '東京都', 35.618369, 139.7406592, 'B', '神社仏閣', '品川神社（しながわじんじゃ）は、東京都品川区北品川三丁目にある神社。'),
    ('浜町公園', null, '東京都', 35.6879032, 139.7895334, 'C', 'その他', '浜町公園（はまちょうこうえん）は、東京都中央区日本橋浜町二丁目にある中央区立の公園である。'),
    ('浜離宮恩賜庭園', 'はまりきゅうおんしていえん', '東京都', 35.66, 139.7636111, 'B', '自然', '海水を引き入れた「潮入の池」を持つ大名庭園、高層ビル群との対比で人気。'),
    ('富岡八幡宮', null, '東京都', 35.6715882, 139.799754, 'B', '神社仏閣', '富岡八幡宮（とみおかはちまんぐう）は、東京都江東区富岡にある八幡神社。通称で深川八幡宮（ふかがわはちまんぐう）とも称される。'),
    ('布多天神社', null, '東京都', 35.6559374, 139.545254, 'B', '神社仏閣', '布多天神社（ふだてんじんしゃ）は、東京都調布市調布ケ丘にある神社。'),
    ('府中の森公園', null, '東京都', 35.6754397, 139.4909432, 'C', 'その他', '府中の森公園（ふちゅうのもりこうえん）は、東京都府中市浅間町にある都立公園。'),
    ('府中市郷土の森公園', null, '東京都', 35.6557792, 139.4744992, 'C', 'その他', '府中市郷土の森公園（ふちゅうし きょうどのもりこうえん）は、東京都府中市矢崎町・是政にある総合公園。'),
    ('府中市郷土の森博物館', null, '東京都', 35.6567023, 139.473316, 'B', '美術館博物館', '府中市郷土の森博物館（ふちゅうしきょうどのもりはくぶつかん）は、東京都府中市にある、多くの建築物を含む森全体が一体となった野外博物館である。'),
    ('府中市美術館', null, '東京都', 35.678748, 139.4920495, 'C', '美術館博物館', '府中市美術館（ふちゅうしびじゅつかん）は、東京都府中市の美術館。'),
    ('浮間公園', null, '東京都', 35.7940355, 139.6938186, 'B', 'その他', '浮間公園（うきまこうえん）は、東京都北区浮間2丁目と板橋区舟渡2丁目の境にある浮間ヶ池を中心にした都立の都市公園（総合公園）。'),
    ('武蔵国分寺', null, '東京都', 35.6934995, 139.471969, 'B', '神社仏閣', '武蔵国分寺（むさしこくぶんじ）は、東京都国分寺市にある真言宗豊山派の寺院。'),
    ('武蔵野の森公園', null, '東京都', 35.6710975, 139.5286735, 'C', 'その他', '武蔵野の森公園（むさしののもりこうえん）は、東京都三鷹市、府中市と調布市にまたがる都立公園である。'),
    ('武蔵野稲荷神社', null, '東京都', 35.7381364, 139.6693759, 'C', '神社仏閣', '武蔵野稲荷神社（むさしのいなりじんじゃ）は東京都練馬区の神社。'),
    ('武蔵野公園', null, '東京都', 35.6877601, 139.5185346, 'C', 'その他', '武蔵野公園（むさしのこうえん）は、東京都府中市多磨町二丁目、小金井市前原町二丁目・東町五丁目にまたがる都立公園。'),
    ('武蔵野市民文化会館', null, '東京都', 35.7114193, 139.5658166, 'C', 'その他', '武蔵野市民文化会館（むさしのしみんぶんかかいかん）は、東京都武蔵野市中町にある文化施設。'),
    ('武蔵野中央公園', null, '東京都', 35.7180864, 139.5586829, 'C', 'その他', '武蔵野中央公園（むさしのちゅうおうこうえん）は、東京都武蔵野市八幡町に広がる芝生が主体の都立公園。'),
